"use client";
/* eslint-disable react-hooks/set-state-in-effect */
import { useCallback,useEffect,useMemo,useState } from "react";

const panel="rounded-2xl border border-[#dfe9e7] bg-white p-5";const input="w-full rounded-xl border border-[#d9e5e2] bg-white px-3 py-2 text-sm";
export default function RoomManagementConsole(){const[data,setData]=useState(null),[error,setError]=useState(""),[query,setQuery]=useState(""),[selectedId,setSelectedId]=useState(null),[view,setView]=useState("Overview"),[draft,setDraft]=useState(null),[saving,setSaving]=useState(false);const load=useCallback(async()=>{const r=await fetch("/api/admin/room-management");const j=await r.json();if(!r.ok)throw new Error(j.error?.message||"Unable to load rooms.");setData(j.data);setSelectedId(id=>id??j.data.rooms[0]?.roomId??null)},[]);useEffect(()=>{load().catch(e=>setError(e.message))},[load]);const rooms=useMemo(()=>data?.rooms.filter(r=>`${r.roomId} ${r.title} ${r.owner.name}`.toLowerCase().includes(query.toLowerCase()))??[],[data,query]);const selected=data?.rooms.find(r=>r.roomId===selectedId)??null;useEffect(()=>{if(selected)setDraft({announcement:selected.announcement??"",language:selected.language??"",tags:selected.tags.join(", "),privacyMode:selected.privacyMode,paidEntryCoins:selected.paidEntryCoins??"",joiningDisabled:selected.joiningDisabled,joiningDisabledUntil:selected.joiningDisabledUntil?.slice(0,16)??""})},[selected]);async function mutate(body){setSaving(true);setError("");try{const r=await fetch("/api/admin/room-management",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({roomId:selected.roomId,...body})});const j=await r.json();if(!r.ok)throw new Error(j.error?.message||"Unable to update room.");await load()}catch(e){setError(e.message)}finally{setSaving(false)}}async function revoke(id){if(!confirm("Remove this room ban?"))return;const r=await fetch(`/api/admin/room-management?banId=${encodeURIComponent(id)}`,{method:"DELETE"});if(!r.ok){const j=await r.json();setError(j.error?.message||"Unable to remove ban.");return}await load()}if(!data)return <div className={panel}>{error||"Loading room management…"}</div>;const roomTabs=["Overview","Members & Seats","Roles & Safety","Settings & Chat","Gifts & PK","Music & Entertainment"];
return <div className="space-y-7"><div><h2 className="text-2xl font-bold">Audio Room Control Center</h2><p className="mt-1 text-sm text-[#71847f]">One operational view for live presence, seats, roles, safety, settings, chat, gifts, PK and room music.</p></div>{error&&<p className="rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>}<div className="grid gap-5 xl:grid-cols-[330px_1fr]"><aside className={`${panel} self-start xl:sticky xl:top-5`}><input className={input} placeholder="Search rooms, owner or ID" value={query} onChange={e=>setQuery(e.target.value)}/><div className="mt-3 max-h-[650px] space-y-2 overflow-y-auto">{rooms.map(room=><button key={room.roomId} onClick={()=>{setSelectedId(room.roomId);setView("Overview")}} className={`w-full rounded-xl border p-3 text-left ${selectedId===room.roomId?"border-[#16877d] bg-[#eef8f6]":"border-[#e5edeb] hover:bg-[#f7faf9]"}`}><div className="flex justify-between gap-2"><b className="truncate text-sm">{room.title}</b><span className={`text-[10px] font-bold ${room.status==="LIVE"?"text-emerald-600":"text-[#71847f]"}`}>{room.status}</span></div><p className="mt-1 text-xs text-[#71847f]">{room.roomId} · {room.owner.name}</p><p className="mt-2 text-[10px] text-[#429387]">{room.uniqueOnline} online · {room.seats.filter(s=>s.occupant).length} seated</p></button>)}{!rooms.length&&<p className="py-8 text-center text-sm text-[#71847f]">No matching rooms.</p>}</div></aside><section className="min-w-0 space-y-5">{selected?<><div className={panel}><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-wider text-[#16877d]">{selected.roomId}</p><h3 className="mt-1 text-xl font-bold">{selected.title}</h3><p className="text-sm text-[#71847f]">Owned by {selected.owner.name} ({selected.owner.publicId})</p></div><div className="flex gap-2"><span className="rounded-full bg-emerald-100 px-3 py-1 text-xs font-bold text-emerald-700">{selected.status}</span><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">rev {selected.revision}</span></div></div><nav className="mt-5 flex gap-1 overflow-x-auto border-b">{roomTabs.map(tab=><button key={tab} onClick={()=>setView(tab)} className={`shrink-0 px-3 py-2 text-xs font-semibold ${view===tab?"border-b-2 border-[#16877d] text-[#087f74]":"text-[#71847f]"}`}>{tab}</button>)}</nav></div>{view==="Overview"&&<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[["Unique online",selected.uniqueOnline],["Socket count",selected.participantCount],["Occupied seats",selected.seats.filter(s=>s.occupant).length],["Gift coins",Number(selected.gifts.coins).toLocaleString()],["Gift events",selected.gifts.count],["Chat messages",selected.messages.length],["Room admins",selected.roles.length],["Music tracks",selected.musicTracks.length]].map(([k,v])=><div key={k} className={panel}><p className="text-xs text-[#71847f]">{k}</p><p className="mt-2 text-2xl font-bold">{v}</p></div>)}</div>}{view==="Members & Seats"&&<div className="grid gap-5 lg:grid-cols-2"><div className={panel}><h4 className="font-bold">Connected members</h4><div className="mt-3 divide-y">{selected.members.map(m=><div key={m.user.publicId} className="py-3 text-sm"><b>{m.user.name}</b> <span className="text-xs text-[#71847f]">{m.user.publicId}</span><p className="text-xs text-[#71847f]">{m.socketCount} socket{m.socketCount===1?"":"s"} · joined {new Date(m.joinedAt).toLocaleString()}</p></div>)}{!selected.members.length&&<p className="py-6 text-sm text-[#71847f]">Nobody is currently connected.</p>}</div></div><div className={panel}><h4 className="font-bold">Canonical seats · revision {selected.seatRevision}</h4><div className="mt-3 grid grid-cols-2 gap-2">{selected.seats.map(s=><div key={s.seatId} className="rounded-xl bg-[#f4f8f7] p-3 text-xs"><b>{s.seatId}</b><p className="mt-1">{s.occupant?`${s.occupant.name} (${s.occupant.publicId})`:"Empty"}</p><p className="mt-1 text-[#71847f]">{s.isLocked?"Locked":"Open"} · {s.isForceMuted?"Force muted":s.isMuted?"Muted":"Mic on"}</p></div>)}</div></div></div>}{view==="Roles & Safety"&&<div className="grid gap-5 lg:grid-cols-2"><div className={panel}><h4 className="font-bold">Delegated roles</h4><div className="mt-3 divide-y">{selected.roles.map(r=><div key={r.id} className="py-3 text-sm"><b>{r.user.name}</b> · {r.role}<p className="text-xs text-[#71847f]">Granted by {r.grantedBy.name}</p></div>)}{!selected.roles.length&&<p className="py-6 text-sm text-[#71847f]">No delegated roles.</p>}</div><p className="mt-3 rounded-xl bg-amber-50 p-3 text-xs text-amber-700">Role assignment remains owner-authorized through the mobile contract; portal override will be enabled after its permission policy is approved.</p></div><div className={panel}><h4 className="font-bold">Active room blacklist</h4><div className="mt-3 divide-y">{data.bans.filter(b=>b.room.roomId===selected.roomId).map(b=><div key={b.id} className="flex items-center justify-between gap-3 py-3 text-sm"><div><b>{b.user.name}</b><p className="text-xs text-[#71847f]">{b.reason||"No reason"} · {b.expiresAt?new Date(b.expiresAt).toLocaleString():"Permanent"}</p></div><button onClick={()=>revoke(b.id)} className="rounded-lg border border-red-200 px-3 py-1 text-xs font-bold text-red-700">Revoke</button></div>)}{!data.bans.some(b=>b.room.roomId===selected.roomId)&&<p className="py-6 text-sm text-[#71847f]">No active bans.</p>}</div></div></div>}{view==="Settings & Chat"&&draft&&<div className="grid gap-5 lg:grid-cols-2"><form className={panel} onSubmit={e=>{e.preventDefault();mutate({action:"UPDATE_SETTINGS",...draft,tags:draft.tags.split(",")})}}><h4 className="font-bold">Canonical room settings</h4><div className="mt-4 space-y-3"><label className="block text-xs font-semibold">Announcement<textarea rows={3} className={input} value={draft.announcement} onChange={e=>setDraft({...draft,announcement:e.target.value})}/></label><div className="grid gap-3 sm:grid-cols-2"><label className="text-xs font-semibold">Language<input className={input} value={draft.language} onChange={e=>setDraft({...draft,language:e.target.value})}/></label><label className="text-xs font-semibold">Privacy<select className={input} value={draft.privacyMode} onChange={e=>setDraft({...draft,privacyMode:e.target.value})}>{["PUBLIC","HIDDEN","PASSWORD","PAID"].map(x=><option key={x}>{x}</option>)}</select></label></div><label className="block text-xs font-semibold">Approved tags<input className={input} value={draft.tags} onChange={e=>setDraft({...draft,tags:e.target.value})}/></label>{draft.privacyMode==="PAID"&&<label className="block text-xs font-semibold">Entry coins<input type="number" className={input} value={draft.paidEntryCoins} onChange={e=>setDraft({...draft,paidEntryCoins:e.target.value})}/></label>}<label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={draft.joiningDisabled} onChange={e=>setDraft({...draft,joiningDisabled:e.target.checked})}/>Pause new joins</label><button disabled={saving} className="rounded-xl bg-[#183f3b] px-4 py-2 text-sm font-bold text-white">Save settings</button></div></form><div className={panel}><div className="flex flex-wrap justify-between gap-2"><h4 className="font-bold">Room chat · revision {selected.chatRevision}</h4><div className="flex gap-2"><button disabled={saving} onClick={()=>mutate({action:"LOCK_CHAT",locked:!selected.chatLocked})} className="rounded-lg border px-3 py-1 text-xs font-bold">{selected.chatLocked?"Unlock":"Lock"}</button><button disabled={saving} onClick={()=>confirm("Clear chat visibility for all clients? Stored records remain available for audit.")&&mutate({action:"CLEAR_CHAT"})} className="rounded-lg border border-red-200 px-3 py-1 text-xs font-bold text-red-700">Clear visibility</button></div></div><p className="mt-2 text-xs text-[#71847f]">Clear Chat advances the visibility revision; it does not permanently delete audit records.</p><div className="mt-3 divide-y">{selected.messages.map(m=><div key={m.id} className="py-3 text-sm"><b>{m.senderName}</b>: {m.body}<p className="text-[10px] text-[#71847f]">{new Date(m.createdAt).toLocaleString()}</p></div>)}{!selected.messages.length&&<p className="py-6 text-sm text-[#71847f]">No visible chat messages.</p>}</div></div></div>}{view==="Gifts & PK"&&<div className="grid gap-5 lg:grid-cols-2"><div className={panel}><h4 className="font-bold">Room gifts</h4><p className="mt-4 text-3xl font-bold">{Number(selected.gifts.coins).toLocaleString()} <span className="text-sm font-normal text-[#71847f]">coins</span></p><p className="mt-1 text-sm text-[#71847f]">Across {selected.gifts.count} committed gift transactions.</p></div><div className={panel}><h4 className="font-bold">PK state</h4>{selected.pk?<div className="mt-4"><b>{selected.pk.status}</b> vs {selected.pk.opponent.title}<p className="mt-2 text-sm text-[#71847f]">Score {selected.pk.leftScore} — {selected.pk.rightScore}</p></div>:<p className="py-6 text-sm text-[#71847f]">No active PK session.</p>}</div></div>}{view==="Music & Entertainment"&&<div className="grid gap-5 lg:grid-cols-2"><div className={panel}><h4 className="font-bold">Private room catalogue</h4><div className="mt-3 divide-y">{selected.musicTracks.map(t=><div key={t.publicId} className="py-3 text-sm"><b>{t.name}</b><p className="text-xs text-[#71847f]">{t.publicId} · {t.mimeType} · {t.active?"Active":"Disabled"}</p></div>)}{!selected.musicTracks.length&&<p className="py-6 text-sm text-[#71847f]">No private music tracks.</p>}</div></div><div className={panel}><h4 className="font-bold">Entertainment snapshot</h4>{selected.entertainment?<pre className="mt-3 max-h-96 overflow-auto rounded-xl bg-[#102f2c] p-4 text-xs text-[#bce8e1]">{JSON.stringify(selected.entertainment,null,2)}</pre>:<p className="py-6 text-sm text-[#71847f]">No active entertainment state.</p>}</div></div>}</>:<div className={panel}>Select a room.</div>}</section></div><section className={panel}><h3 className="font-bold">Moderation history</h3><div className="mt-3 divide-y">{data.logs.slice(0,100).map(l=><div key={l.id} className="py-3 text-sm"><b>{l.action.replaceAll("_"," ")}</b> · {l.room.roomId}<p className="text-xs text-[#71847f]">{l.actor.name}{l.target?` → ${l.target.name}`:""} · {new Date(l.createdAt).toLocaleString()} {l.reason?`· ${l.reason}`:""}</p></div>)}</div></section></div>}
